package main

import (
	"bufio"
	"fmt"
	"io"
	"net"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

type ProxyServer struct {
	backend    string
	listenAddr string
	connPool   sync.Pool
}

func NewProxyServer(listen, backend string) *ProxyServer {
	return &ProxyServer{
		backend:    backend,
		listenAddr: listen,
		connPool: sync.Pool{
			New: func() interface{} {
				conn, err := net.Dial("tcp", backend)
				if err != nil {
					return nil
				}
				return conn
			},
		},
	}
}

func (p *ProxyServer) normalizeHeaders(headers http.Header) http.Header {
	normalized := make(http.Header)
	for key, values := range headers {
		canonical := http.CanonicalHeaderKey(key)
		for _, v := range values {
			normalized.Add(canonical, strings.TrimSpace(v))
		}
	}
	return normalized
}

func (p *ProxyServer) determineBodyLength(req *http.Request) int64 {
	// Priority resolution: if both Transfer-Encoding and Content-Length
	// are present, we need to resolve the ambiguity
	te := req.Header.Get("Transfer-Encoding")
	cl := req.Header.Get("Content-Length")

	if te != "" && cl != "" {
		// RFC 7230 Section 3.3.3: If Transfer-Encoding is present,
		// Content-Length MUST be ignored. Remove CL and use chunked.
		req.Header.Del("Content-Length")
		return -1 // chunked
	}

	if te != "" {
		return -1 // chunked
	}

	if cl != "" {
		length, err := strconv.ParseInt(cl, 10, 64)
		if err != nil {
			return 0
		}
		return length
	}

	return 0
}

func (p *ProxyServer) forwardRequest(clientConn net.Conn, req *http.Request) error {
	backendConn := p.connPool.Get()
	if backendConn == nil {
		return fmt.Errorf("failed to get backend connection")
	}
	defer p.connPool.Put(backendConn)

	bc := backendConn.(net.Conn)

	req.Header = p.normalizeHeaders(req.Header)
	bodyLen := p.determineBodyLength(req)

	// Write request line
	reqLine := fmt.Sprintf("%s %s HTTP/1.1\r\n", req.Method, req.URL.RequestURI())
	bc.Write([]byte(reqLine))

	// Write headers
	for key, values := range req.Header {
		for _, v := range values {
			headerLine := fmt.Sprintf("%s: %s\r\n", key, v)
			bc.Write([]byte(headerLine))
		}
	}
	bc.Write([]byte("\r\n"))

	// Forward body based on determined length
	if bodyLen > 0 {
		io.CopyN(bc, req.Body, bodyLen)
	} else if bodyLen == -1 {
		io.Copy(bc, req.Body)
	}

	// Read and forward response
	respReader := bufio.NewReader(bc)
	resp, err := http.ReadResponse(respReader, req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	resp.Write(clientConn)
	return nil
}

func (p *ProxyServer) handleConnection(conn net.Conn) {
	defer conn.Close()
	reader := bufio.NewReader(conn)

	for {
		req, err := http.ReadRequest(reader)
		if err != nil {
			return
		}

		var wg sync.WaitGroup
		wg.Add(1)
		go func() {
			defer wg.Done()
			if err := p.forwardRequest(conn, req); err != nil {
				fmt.Printf("forward error: %v\n", err)
			}
		}()
		wg.Wait()
	}
}

func (p *ProxyServer) Start() error {
	listener, err := net.Listen("tcp", p.listenAddr)
	if err != nil {
		return err
	}
	defer listener.Close()

	fmt.Printf("Proxy listening on %s, forwarding to %s\n", p.listenAddr, p.backend)

	for {
		conn, err := listener.Accept()
		if err != nil {
			continue
		}
		go p.handleConnection(conn)
	}
}

func main() {
	proxy := NewProxyServer(":8080", "127.0.0.1:9090")
	if err := proxy.Start(); err != nil {
		fmt.Printf("Failed to start proxy: %v\n", err)
	}
}
